contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // run takes inputs used to call C.transfer
    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public payable {
        require(_tos.length > 0);
        // record test contract balance before the call
        uint balBefore = address(this).balance;
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }
        // General rule: if the call did not revert it must have returned true,
        // and the test contract's balance must be unchanged (the transfer function does not handle Ether).
        assert(reverted || (ret == true && address(this).balance == balBefore));
    }
    receive() external payable { }
}

