contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public payable {
        // require non-empty recipients and require that v * 10**_decimals does not overflow uint
        require(_tos.length > 0);
        // ensure 10**_decimals is representable and multiplication won't overflow: v <= type(uint).max / (10**_decimals)
        // bound _decimals to a reasonable range to keep 10**_decimals computable in solidity
        require(_decimals <= 77); // 10**78 > uint256 max, so 77 is safe
        uint factor = 1;
        for (uint i = 0; i < _decimals; i++) { factor *= 10; }
        require(factor > 0);
        require(v <= type(uint).max / factor);

        bool reverted;
        bool returned;
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool r) {
            reverted = false;
            returned = r;
        } catch {
            reverted = true;
            returned = false;
        }

        // General rule: under the above preconditions, the call either reverted or returned true
        assert(reverted || returned == true);
    }
    receive() external payable { }
}

